mapper.select:
select id, receiving_unit, receiving_address, product_name, specification_model, box_number, reel_number, unit, quantity, shipping_date, contact_phone, remarks, courier_number, supplier_unit, supplier_contact_person, supplier_contact_phone, create_by, create_time, update_by, update_time 
from sy_outbound_records 
where id = #{id}

select id, receiving_unit, receiving_address, product_name, specification_model, box_number, reel_number, unit, quantity, shipping_date, contact_phone, remarks, courier_number, supplier_unit, supplier_contact_person, supplier_contact_phone, create_by, create_time, update_by, update_time from sy_outbound_records
and receiving_unit like concat('%', #{receivingUnit}, '%') and receiving_address like concat('%', #{receivingAddress}, '%') and product_name like concat('%', #{productName}, '%') and specification_model like concat('%', #{specificationModel}, '%') and box_number like concat('%', #{boxNumber}, '%') and reel_number like concat('%', #{reelNumber}, '%') and unit = #{unit} and quantity = #{quantity} and shipping_date = #{shippingDate} and contact_phone like concat('%', #{contactPhone}, '%') and remarks like concat('%', #{remarks}, '%') and courier_number like concat('%', #{courierNumber}, '%') and supplier_unit like concat('%', #{supplierUnit}, '%') and supplier_contact_person like concat('%', #{supplierContactPerson}, '%') and supplier_contact_phone like concat('%', #{supplierContactPhone}, '%')
and shipping_date >= #{shippingDateStart} and shipping_date <= #{shippingDateEnd}
and receiving_unit like concat('%', #{value}, '%') and product_name like concat('%', #{value}, '%') and box_number like concat('%', #{value}, '%') and reel_number like concat('%', #{value}, '%') and courier_number like concat('%', #{value}, '%') and supplier_unit like concat('%', #{value}, '%') and contact_phone like concat('%', #{value}, '%') and supplier_contact_person like concat('%', #{value}, '%') and supplier_contact_phone like concat('%', #{value}, '%')
order by create_time desc
LIMIT #{StarRow} , #{PageSize}

mapper.update:
update sy_outbound_records
receiving_unit = #{receivingUnit}, receiving_address = #{receivingAddress}, product_name = #{productName}, specification_model = #{specificationModel}, unit = #{unit}, shipping_date = #{shippingDate}, contact_phone = #{contactPhone}, remarks = #{remarks}, courier_number = #{courierNumber}, supplier_unit = #{supplierUnit}, supplier_contact_person = #{supplierContactPerson}, supplier_contact_phone = #{supplierContactPhone}, update_by = #{updateBy}, update_time = now()
where id = #{id}
